--!strict
local RunService=game:GetService("RunService");local Config=require(game:GetService("ReplicatedStorage").Modules.DevelopmentConfig);if not RunService:IsStudio()or not Config.EnableDiagnostics then return end;local Profiles=require(script.Parent.Services.PlayerProfileService);local Queue=require(script.Parent.Services.QueueService);local Tower=require(script.Parent.Services.TowerService);local remotes=require(script.Parent.Services.RemoteService).Ensure()
task.spawn(function()while task.wait(Config.DiagnosticsInterval)do local world=workspace:FindFirstChild("PartyObbyWorld");local runtime=world and world:FindFirstChild("Runtime");local matches=runtime and runtime:FindFirstChild("ActiveMatches");local items=workspace:FindFirstChild("TemporaryPartyItems");local payload={ActiveRuntimeMaps=matches and #matches:GetChildren()or 0,ActiveTemporaryItems=items and #items:GetChildren()or 0,LoadedProfiles=Profiles.CountLoaded(),QueuedPlayers=Queue.Count("CasualRace")+Queue.Count("RankedRace"),TowerRuns=Tower.Count()};print(string.format("[Diagnostics] Maps=%d Items=%d Profiles=%d Queue=%d Towers=%d",payload.ActiveRuntimeMaps,payload.ActiveTemporaryItems,payload.LoadedProfiles,payload.QueuedPlayers,payload.TowerRuns));remotes.DiagnosticsUpdated:FireAllClients(payload)end end)
